static uint32_t get_file_browser_vol(void * p_param)
{
    uint32_t        vol;
    ui_screen_file_browser_play_obj_t * p_screen_param;

    p_screen_param      = p_param;

    vol                 = 0;

    switch (p_screen_param->file_browser_type)
    {
        case file_browser_mp3:
            vol = app_musicplayer_get_vol();

            if (vol > MUSIC_MVOL_LEVEL_MAX)
                vol = MUSIC_MVOL_LEVEL_MAX;

            break;

        case file_browser_amr:
            vol = app_recorder_getvol();

            if (vol > MUSIC_MVOL_LEVEL_MAX)
                vol = MUSIC_MVOL_LEVEL_MAX;

            break;

        default:
            break;
        }

    return vol;
}

static uint32_t set_file_browser_vol(void * p_param,uint32_t status)
{
    uint32_t        vol;

    ui_screen_file_browser_play_obj_t * p_screen_param;

    p_screen_param      = p_param;

    vol                 = 0;

    switch (p_screen_param->file_browser_type)
    {
        case file_browser_mp3:
            vol = app_musicplayer_get_vol();

            if (status) {
                if (vol < MUSIC_MVOL_LEVEL_MAX)
                    vol++;
                else 
                    vol = MUSIC_MVOL_LEVEL_MAX;
                }
            else {
                if (vol > MUSIC_MVOL_LEVEL_MIN)
                    vol--;
                else 
                    vol = MUSIC_MVOL_LEVEL_MIN;

                }

            app_musicplayer_set_vol(vol);
            break;

        case file_browser_amr:
            vol = app_recorder_getvol();

            if (status) {
                if (vol < MUSIC_MVOL_LEVEL_MAX)
                    vol++;
                else 
                    vol = MUSIC_MVOL_LEVEL_MAX;
                }
            else {
                if (vol > MUSIC_MVOL_LEVEL_MIN)
                    vol--;
                else 
                    vol = MUSIC_MVOL_LEVEL_MIN;
                }

            app_recorder_setvol(vol);
            break;

        default:
            break;
        }

    return vol;
}

