void ui_ScreenFileBrowserPlay_screen_uninit(lv_obj_t * win,void * param)
{
    lv_obj_t *      ui_ScreenFileBrowserPlay = NULL;

    ui_ScreenFileBrowserPlay = lv_obj_get_user_data(win);

    if (ui_ScreenFileBrowserPlay) {
        ui_screen_file_browser_play_obj_t * p_screen_param;

        p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_ScreenFileBrowserPlay);
        file_browser_stop(p_screen_param);
        screen_file_browser_player_timer_stop(ui_ScreenFileBrowserPlay);

        __inf("FileBrowserPlay lv_obj_del_screen_ready_cb:%d",p_screen_param->file_browser_type);

        switch (p_screen_param->file_browser_type)
        {
            case file_browser_mp3:
                //app_musicplayer_set_playmode(p_screen_param->music_play_mode);
                app_musicplayer_status_set_func_callback(NULL,NULL);

                //app_musicplayer_reset_pre_playtime();
                break;

            case file_browser_amr:
                app_recorder_status_set_func_callback(NULL,NULL);

                if (p_screen_param->flag_create_record_task == 1) {
                    //app_srv_recording_deinit(g_recorder_srv);
                    //g_recorder_srv = NULL;
                    }

                break;
            }

        ps_data_msg_send_music_pending_restore(1);
        lv_obj_del_delayed_callback(ui_ScreenFileBrowserPlay,100,lv_obj_del_screen_ready_cb);
        }

    lv_obj_set_user_data(win,NULL);

    __inf("FileBrowserPlay ui_ScreenFileBrowserPlay_screen_uninit");
}


void ui_ScreenFileBrowserPlay_screen_focus(lv_obj_t * win,void * param)
{
    lv_obj_t *      ui_ScreenFileBrowserPlay = NULL;
    ui_screen_file_browser_play_obj_t * p_screen_param;
    uint32_t        play_time;
    uint32_t        per;
    uint8_t         time_str[10];

    ui_ScreenFileBrowserPlay = lv_obj_get_user_data(win);
    p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_ScreenFileBrowserPlay);

    file_browser_set_play_path(p_screen_param);

    p_screen_param->file_browser_duration = get_file_browser_duration(p_screen_param);

    play_time           = get_file_browser_playtime(p_screen_param);
    play_time           = play_time / 10;

    per                 = play_time / p_screen_param->file_browser_duration;

    if (per > 100)
        per = 100;

    lv_slider_set_value(p_screen_param->obj_slider,per,LV_ANIM_OFF);

    play_time           = play_time / 100;

    sprintf(time_str,"%02d:%02d",(int) play_time / 60,(int) play_time % 60);
    lv_label_set_text(p_screen_param->obj_label_play_time,time_str);
    sprintf(time_str,"%02d:%02d",(int) p_screen_param->file_browser_duration / 60,
        (int) p_screen_param->file_browser_duration % 60);
    lv_label_set_text(p_screen_param->obj_label_duration,time_str);

    lv_disp_load_scr(ui_ScreenFileBrowserPlay);

    {
        file_browser_play_status_param_t file_browser_play_status_param;

        file_browser_play_status_param.p_screen = ui_ScreenFileBrowserPlay;
        file_browser_play_status_update_callback_action(&file_browser_play_status_param,0);
        }
    screen_file_browser_player_timer_start(ui_ScreenFileBrowserPlay);
}


