void file_browser_play_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_file_browser_play_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_LEFT:
            {
                //app_file_browserer_fast_rewind();
                }

        case LV_KEY_RIGHT:
            {
                //app_file_browserer_fast_forward();
                }
            break;

        case LV_KEY_UP:
            {
                uint32_t        vol;

                vol                 = set_file_browser_vol(p_screen_param,1);
                lv_img_set_src(p_screen_param->obj_img_vol,ui_img_vol[vol]);

                }
            break;

        case LV_KEY_DOWN:
            {

                uint32_t        vol;

                vol                 = set_file_browser_vol(p_screen_param,0);
                lv_img_set_src(p_screen_param->obj_img_vol,ui_img_vol[vol]);
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                alv_am_win_enter(NULL,"file_browser_option",NULL);
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_ENTER:
            {
                uint8_t         play_status;

                file_browser_play_pause(p_screen_param);
                play_status         = get_file_browser_play_status(p_screen_param);
                lv_img_set_src(p_screen_param->obj_img_play,ui_img_play_status[play_status]);
                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}



void screen_file_browser_player_time_update(ui_screen_file_browser_play_obj_t * p_screen_param)
{
    uint32_t        play_time;
    uint32_t        per;
    uint8_t         time_str[10];

    //__inf("app_file_browserplayer_play_time:%d,%d",app_file_browserplayer_play_time(),app_file_browserplayer_play_duration());
    play_time           = get_file_browser_playtime(p_screen_param);
    play_time           = play_time / 10;

    per                 = play_time / p_screen_param->file_browser_duration;

    if (per > 100)
        per = 100;

    lv_slider_set_value(p_screen_param->obj_slider,per,LV_ANIM_OFF);

    play_time           = play_time / 100;

    sprintf(time_str,"%02d:%02d",(int) play_time / 60,(int) play_time % 60);
    lv_label_set_text(p_screen_param->obj_label_play_time,time_str);
}


void screen_file_browser_player_timer_stop(lv_obj_t * ui_Screen)
{
    ui_screen_file_browser_play_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer != NULL) {
        lv_timer_del(p_screen_param->handle_timer);
        p_screen_param->handle_timer = NULL;
        }


}



void screen_file_browser_player_timer_pause(lv_obj_t * ui_Screen)
{
    ui_screen_file_browser_play_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer != NULL) {
        lv_timer_pause(p_screen_param->handle_timer);
        }

}


void screen_file_browser_player_timer_resume(lv_obj_t * ui_Screen)
{
    ui_screen_file_browser_play_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer != NULL) {
        lv_timer_resume(p_screen_param->handle_timer);
        }


}



static void screen_file_browser_player_timer_event_cb(struct _lv_timer_t *timer)
{
    lv_obj_t *      ui_Screen;
    ui_screen_file_browser_play_obj_t * p_screen_param;

    ui_Screen           = timer->user_data;
    p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_Screen);


    screen_file_browser_player_time_update(p_screen_param);


}


void screen_file_browser_player_timer_start(lv_obj_t * ui_Screen)
{
    ui_screen_file_browser_play_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_file_browser_play_obj_t *) lv_obj_get_user_data(ui_Screen);


    if (p_screen_param->handle_timer == NULL) {
        p_screen_param->handle_timer = lv_timer_create(screen_file_browser_player_timer_event_cb,1000,ui_Screen);
        }

}






